package GUI;
import Program.model.User; import Program.service.*; import javafx.scene.control.*; import javafx.scene.layout.*;
public class SettingsUI extends ScrollPane {public SettingsUI(User user,MainUI app,AuthService auth){setFitToWidth(true);VBox p=UIFactory.page("Settings","Profile, security, appearance and local data controls.");TextField name=UIFactory.field("Full name");name.setText(user.getFullName());Label username=new Label("Username: "+user.getUsername());Button save=UIFactory.button("Save profile","primary-button");save.setOnAction(e->{try{auth.updateProfile(user,name.getText());UIFactory.info("Profile updated","Your display name has been saved.");}catch(Exception ex){UIFactory.error(ex.getMessage());}});PasswordField old=new PasswordField(),fresh=new PasswordField();old.setPromptText("Current password");fresh.setPromptText("New password");Button change=UIFactory.button("Change password","secondary-button");change.setOnAction(e->{try{auth.changePassword(user,old.getText(),fresh.getText());UIFactory.info("Password changed","Your password hash was updated.");old.clear();fresh.clear();}catch(Exception ex){UIFactory.error(ex.getMessage());}});DataService dataService=new DataService();Button export=UIFactory.button("Export data","secondary-button"),clear=UIFactory.button("Clear financial data","danger-button");export.setOnAction(e->{dataService.exportUserData(user);UIFactory.info("Export created","Saved local export in File/reports.");});clear.setOnAction(e->{if(new Alert(Alert.AlertType.CONFIRMATION,"Delete this user's expenses, income, and budgets?",ButtonType.YES,ButtonType.NO).showAndWait().orElse(ButtonType.NO)==ButtonType.YES){dataService.clearUserData(user);UIFactory.info("Financial data cleared","Your account remains active.");}});VBox profile=box("PROFILE",name,username,save),security=box("SECURITY",old,fresh,change),appearance=box("APPEARANCE",new Label("Dark fintech theme is active.")),data=box("DATA",new Label("Export or clear only your financial records."),new HBox(10,export,clear));p.getChildren().addAll(profile,security,appearance,data);setContent(p);}private VBox box(String title,javafx.scene.Node... nodes){VBox b=new VBox(10);b.getChildren().add(new Label(title));b.getChildren().addAll(nodes);b.setPadding(new javafx.geometry.Insets(18));b.getStyleClass().add("glass-card");return b;}}
